insert into public.fenomens_astronomics (codi, tipus_codi, periodicitat, publicable_calendari, textos) values
  ('conjuncio-lluna-jupiter', 'conjuncio', 'ocasional', true, '{"ca":{"nom":"Aproximació de Lluna i Júpiter","descripcio":"Des de la Terra, Lluna i Júpiter semblen propers al cel, tot i que estan molt separats a l''espai.","consell_general":"Busqueu un horitzó clar i consulteu l''hora i les condicions locals; la proximitat és aparent."}}'::jsonb),
  ('conjuncio-lluna-mart', 'conjuncio', 'ocasional', true, '{"ca":{"nom":"Aproximació de Lluna i Mart","descripcio":"Des de la Terra, Lluna i Mart semblen propers al cel, tot i que estan molt separats a l''espai.","consell_general":"Busqueu un horitzó clar i consulteu l''hora i les condicions locals; la proximitat és aparent."}}'::jsonb),
  ('conjuncio-lluna-venus', 'conjuncio', 'ocasional', true, '{"ca":{"nom":"Aproximació de Lluna i Venus","descripcio":"Des de la Terra, Lluna i Venus semblen propers al cel, tot i que estan molt separats a l''espai.","consell_general":"Busqueu un horitzó clar i consulteu l''hora i les condicions locals; la proximitat és aparent."}}'::jsonb),
  ('conjuncio-mart-jupiter', 'conjuncio', 'ocasional', true, '{"ca":{"nom":"Aproximació de Mart i Júpiter","descripcio":"Des de la Terra, Mart i Júpiter semblen propers al cel, tot i que estan molt separats a l''espai.","consell_general":"Busqueu un horitzó clar i consulteu l''hora i les condicions locals; la proximitat és aparent."}}'::jsonb),
  ('lluna-nova', 'fase_llunar', 'mensual', true, '{"ca":{"nom":"Lluna nova","descripcio":"Fase en què la cara il·luminada de la Lluna no mira cap a la Terra. La Lluna no és observable, però el cel és més fosc.","consell_general":"Aprofiteu la foscor per observar objectes febles; la meteorologia i la contaminació lumínica continuen sent determinants."}}'::jsonb),
  ('lluna-plena', 'fase_llunar', 'mensual', true, '{"ca":{"nom":"Lluna plena","descripcio":"Fase en què veiem gairebé tot el disc lunar il·luminat.","consell_general":"La Lluna plena és fàcil de veure, però la seva llum dificulta observar objectes febles."}}'::jsonb),
  ('superlluna-plena', 'superlluna', 'ocasional', true, '{"ca":{"nom":"Superlluna plena","descripcio":"Lluna plena propera al perigeu segons el criteri del 90 % del recorregut entre apogeu i perigeu; la diferència aparent pot ser subtil.","consell_general":"Observeu-la a ull nu. No espereu un canvi de mida espectacular sense comparar fotografies preses amb el mateix equip."}}'::jsonb)
